/* Original Glasshouse apparatus for Physics 1–8. Source evidence: section-local PDFs. */
(()=>{'use strict';const K=window.GlassPhysicsKit,D={},g=9.8,pi=Math.PI;
const N=(key,label,min,max,step,value,unit='')=>({key,label,min,max,step,value,unit});
const O=(key,label,value,options)=>({key,label,value,options:options.map(([value,label])=>({value,label}))});
const f=K.fmt,T=(x,y,s,z=16,k='ink')=>K.text(x,y,s,k,z),A=K.arrow,L=K.line,C=K.circle,R=K.rect,P=K.path;
const rad=d=>d*pi/180,clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),r=(label,value,unit='')=>({label,value,unit});
const head=s=>T(480,48,s,21),note=s=>T(480,480,s,14,'muted');
const info=(lines,x=750,y=130)=>lines.map((s,i)=>T(x,y+i*32,s,16)).join('');
const step=(title,why,equation,visual)=>({title,why,equation,visual});
const target=(prompt,answer,unit,steps)=>({prompt,answer,unit,steps,tolerance:Math.max(1e-7,Math.abs(answer)*.005)});
const physical=(duration=6)=>({label:'Run experiment',kind:'physical',duration});
const staged=(duration=8,note='The moving marker shows a controlled measurement, not free motion.')=>({label:'Explore apparatus',kind:'construction',duration,note});
function spring(x1,x2,y,amp=15){let d=`M${x1},${y}`;for(let i=1;i<=20;i++)d+=` L${x1+(x2-x1)*i/21},${y+(i%2?amp:-amp)}`;return P(d+` L${x2},${y}`,'aqua',3);}
function cart(x,y,m=2,label='cart'){const w=34+8*Math.sqrt(m);return R(x-w/2,y-26,w,32,'surface',4)+C(x-w*.3,y+9,7,'wire')+C(x+w*.3,y+9,7,'wire')+T(x,y-36,label,14);}
function rail(y=350){let q=L(65,y,900,y,'wire',4);for(let x=80;x<=900;x+=40)q+=L(x,y+2,x-12,y+15,'line',2);return q;}
function ball(x,y,m=2){return C(x,y,9+3*Math.sqrt(m),'coral')+C(x-4,y-4,3,'paper',.65);}
function vec(x,y,vx,vy,scale=10,kind='coral',label=''){const dx=vx*scale,dy=-vy*scale;return A(x,y,x+dx,y+dy,kind,3)+(label?T(x+dx+(dy>8?34:0),y+dy+(dy>8?-6:-17),label,14,kind):'');}
function energy(x,y,label,val,max,kind='coral'){let h=clamp(val/max,0,1)*170;return R(x-24,y-170,48,170,'surface',3)+R(x-21,y-h,42,h,kind,2)+T(x,y+25,label,15)+T(x,y-188,`${f(val)} J`,14);}
function def(id,title,intro,controls,compute,scene,steps,targetFn,animation,pages,noteText){D[id]={title,intro,controls,compute,scene:(s,m,t,stage)=>`<g data-gp-model="mechanics-${id.replace('.','-')}">${scene(s,m,t,stage)}</g>`,steps,target:targetFn,animation,source:{section:id,file:`books/physics/chapter-${id.split('.')[0].padStart(2,'0')}.pdf`,pages,note:noteText+' Original section teaching experiment; not a simulation of every exercise.'}};}

def('1.1','Measure an object against a real scale','Slide the object end and change the ruler unit. The object keeps its physical length while the divisions and numerical reading change.',[N('length','Object length',5,90,1,45,'cm'),O('unit','Ruler divisions','cm',[['cm','Centimeters'],['mm','Millimeters'],['m','Meters']])],s=>({reading:s.length*({cm:1,mm:10,m:.01}[s.unit]),readouts:[r('Object length',s.length/100,'m'),r('Reading',s.length*({cm:1,mm:10,m:.01}[s.unit]),s.unit)]}),(s,m,t)=>{let q=head('Align the left end with zero')+R(110,200,7*s.length,58,'coral',3)+L(110+7*s.length,185,110+7*s.length,355,'aqua',2)+R(110,300,700,65,'surface',2);let count=s.unit==='mm'?100:s.unit==='cm'?20:10;for(let i=0;i<=count;i++)q+=L(110+700*i/count,300,110+700*i/count,300+(i%5===0?32:15),'wire',1);for(let i=0;i<=5;i++)q+=T(110+140*i,352,f(i*20*({cm:1,mm:10,m:.01}[s.unit])),14);q+=C(110+7*s.length*Math.min(1,t/8),215,5,'paper')+T(470,408,`Same object: ${f(m.reading)} ${s.unit}`,20);return q+note('Scale fixed: ruler is 1.00 m long; minor divisions depend on the chosen unit.');},[step('Choose a standard','Length compares two endpoints with a reproducible unit.','L = x_right − x_left','The left end remains at the zero mark.'),step('Change the unit','Conversion changes the number of units, not the object.','1 m = 100 cm = 1000 mm','The ruler ticks change while the coral bar stays the same length.'),step('Cancel units','Multiply by a conversion factor equal to one.','L(m) = L(cm) × (1 m / 100 cm)','Read the right endpoint and convert it to meters.')],(s,m)=>target(`Convert the measured ${s.length} cm to meters.`,s.length/100,'m',[`${s.length} cm × (1 m / 100 cm)`,`${f(s.length/100)} m`]),staged(),[1,2,3],'§1.1 SI length, prefixes, chain-link conversion. Unit controls alter scale spacing, not physical length.');

def('1.2','Count a clock’s repeated cycles','An ideal laboratory oscillator marks time by repeating. Choose its frequency and the number of complete cycles counted; this slowed illustration is not an atomic-clock simulation.',[N('frequency','Oscillator frequency',1,10,1,4,'Hz'),N('cycles','Complete cycles counted',2,20,1,8)],s=>({duration:s.cycles/s.frequency,phase:2*pi*s.frequency*s.time,readouts:[r('Period',1/s.frequency,'s'),r('Counted duration',s.cycles/s.frequency,'s'),r('Cycles at model time',s.frequency*s.time)]}),(s,m,t)=>{let q=head('One cycle is one repeat of the same phase')+C(310,250,118,'surface')+L(310,130,310,150,'wire',4)+A(310,250,310+90*Math.sin(m.phase),250-90*Math.cos(m.phase),'coral',5)+C(310,250,8,'wire');for(let i=0;i<s.cycles;i++){let x=490+(i%10)*34,y=185+Math.floor(i/10)*90;q+=C(x,y,10,i<Math.floor(s.frequency*t)?'coral':'surface');}return q+T(650,340,`${s.cycles} cycles ÷ ${s.frequency} Hz`,21)+note('Ideal oscillator: each turn is one full cycle; time in seconds is controlled below.');},[step('Identify one repeat','A full phase repeat, not half a swing, counts as one cycle.','T = 1/f','The rotating hand returns to the top once each period.'),step('Count cycles','Identical repeats provide equal time intervals.','Δt = N T','Each filled dot records a completed cycle.'),step('Convert frequency to time','Hertz means cycles per second, so cycles divided by hertz gives seconds.','Δt = N/f','Increasing frequency packs more cycles into each second.')],(s,m)=>target(`At ${s.frequency} Hz, how long do ${s.cycles} full cycles take?`,m.duration,'s',[`One cycle: T = 1/${s.frequency} s`,`Δt = ${s.cycles}/${s.frequency} = ${f(m.duration)} s`]),physical(20),[5,6],'§1.2 repeating phenomena and time standards. Ideal low-frequency oscillator illustrates counting only.');

def('1.3','Build and weigh a uniform cube','Change the cube size and material density. More volume or more mass in each unit volume increases the mass shown by the balance.',[N('side','Cube edge',2,10,1,5,'cm'),N('density','Uniform density',500,8000,500,2000,'kg/m³')],s=>({volume:(s.side/100)**3,mass:s.density*(s.side/100)**3,readouts:[r('Volume',(s.side/100)**3,'m³'),r('Mass',s.density*(s.side/100)**3,'kg')]}),(s,m,t)=>{let side=12*s.side,x=300-side/2,y=300-side,q=head('Density tells how much mass fills each volume')+P(`M${x},${y}l${side*.2},${-side*.2}h${side}l${-side*.2},${side*.2}Z`,'line',2,'paper')+P(`M${x+side},${y}l${side*.2},${-side*.2}v${side}l${-side*.2},${side*.2}Z`,'line',2,'aqua')+R(x,y,side,side,'surface',3);for(let i=0;i<Math.round(s.density/500);i++){let xx=x+side*(.12+(i%4)*.25),yy=y+side*(.15+Math.floor(i/4)*.22);q+=C(xx,yy,2+s.side*.18,'coral');}q+=L(x,y+side*Math.min(t/8,1),x+side,y+side*Math.min(t/8,1),'aqua',3)+R(180,315,240,65,'surface')+T(300,355,`${f(m.mass)} kg`,22)+L(460,300,800,300,'wire',4);for(let i=0;i<Math.ceil(m.mass*2);i++)q+=R(475+(i%8)*36,278-Math.floor(i/8)*25,29,21,'aqua',2);return q+info([`Edge = ${s.side} cm`,`V = ${f(m.volume)} m³`,`m = ρV = ${f(m.mass)} kg`],690,130)+note('Dots represent density schematically; each aqua reference weight is 0.5 kg (last one rounded up).');},[step('Measure three edges','Volume is a three-dimensional quantity. Doubling every edge makes eight times the volume.','V = L³','The cube expands in both visible dimensions; its depth also equals its edge.'),step('Use a uniform density','A uniform material has the same mass in each equal volume.','ρ = m/V','Increasing density adds material markers inside the same cube.'),step('Compute mass','Convert centimeters to meters before cubing.','m = ρ(L/100)³','The balance reading and reference weights respond to cube mass.')],(s,m)=>target(`Find the mass of a uniform cube of edge ${s.side} cm and density ${s.density} kg/m³.`,m.mass,'kg',[`L = ${s.side/100} m; V = L³ = ${f(m.volume)} m³`,`m = ${s.density} × ${f(m.volume)} = ${f(m.mass)} kg`]),staged(),[6,7],'§1.3 density ρ=m/V. Uses density only; the edition’s historic kilogram definition is not used.');

// One-dimensional tracks: fixed 12 px/m, no automatic rescaling.
function track(x,y=330){let q=rail(y+20);for(let v=-10;v<=50;v+=10)q+=L(200+12*v,y+18,200+12*v,y+33,'line',2)+T(200+12*v,y+58,`${v} m`,13);return q;}
def('2.1','Send a cart out and back','Observe the traveled path separately from the arrow joining the initial and final positions. Returning changes total distance even when final displacement is small.',[N('start','Initial position',-5,5,1,0,'m'),N('turn','Turnaround position',10,25,1,20,'m'),N('finish','Final position',-5,8,1,4,'m'),N('duration','Whole-trip duration',4,10,1,8,'s')],s=>{let distance=s.turn-s.start+s.turn-s.finish,u=Math.min(s.time/s.duration,1),fraction=(s.turn-s.start)/distance,pos=u<=fraction?s.start+u*distance:s.turn-(u-fraction)*distance;return{pos,distance,displacement:s.finish-s.start,avg:(s.finish-s.start)/s.duration,speed:distance/s.duration,readouts:[r('Current position',pos,'m'),r('Net displacement',s.finish-s.start,'m'),r('Distance for whole trip',distance,'m'),r('Whole-trip average velocity',(s.finish-s.start)/s.duration,'m/s')]};},(s,m)=>head('Travel length is not the same as displacement')+track()+L(200+12*s.start,245,200+12*s.turn,245,'aqua',6)+L(200+12*s.turn,267,200+12*s.finish,267,'aqua',6)+A(200+12*s.start,185,200+12*s.finish,185,'coral',4)+cart(200+12*m.pos,320,2)+info([`distance = ${f(m.distance)} m`,`Δx = ${f(m.displacement)} m`,`average speed = ${f(m.speed)} m/s`],740,100)+note('Fixed spatial ruler; ideal instantaneous reversal at the turnaround, constant speed otherwise.'),[step('Read endpoints','Displacement records only the change of position, not the intermediate route.','Δx = x_f − x_i','The coral arrow joins the start and finish.'),step('Add traveled segments','Distance adds the lengths of both legs without cancelling directions.','distance = (x_turn − x_i) + (x_turn − x_f)','The two aqua segments show the outgoing and returning legs.'),step('Divide by the same total time','Average velocity uses displacement; average speed uses total traveled distance.','v_avg = Δx/Δt; speed_avg = distance/Δt','A nearly returning cart can have large average speed and small average velocity.')],(s,m)=>target(`For the full ${s.duration} s trip from ${s.start} m via ${s.turn} m to ${s.finish} m, find average velocity.`,m.avg,'m/s',[`Δx = ${s.finish} − (${s.start}) = ${m.displacement} m`,`v_avg = ${m.displacement}/${s.duration} = ${f(m.avg)} m/s`]),physical(10),[1,2,3],'§2.1 displacement, average velocity and average speed; out-and-back special case.');

def('2.2','Shrink a moving-cart measurement window','The cart follows x=ut+bt². Two timing gates estimate its speed over a short forward interval; the instantaneous velocity belongs to the first gate.',[N('u','Initial velocity u',-2,4,1,2,'m/s'),N('b','Quadratic coefficient b',.1,.8,.1,.4,'m/s²'),N('window','Gate time separation Δt',.1,1,.1,.5,'s')],s=>{let t=s.time,x=s.u*t+s.b*t*t,x2=s.u*(t+s.window)+s.b*(t+s.window)**2;return{x,x2,v:s.u+2*s.b*t,average:(x2-x)/s.window,readouts:[r('Instantaneous velocity',s.u+2*s.b*t,'m/s'),r('Two-gate average velocity',(x2-x)/s.window,'m/s'),r('Gate separation',x2-x,'m')]};},(s,m)=>head('Bring the second measurement closer in time')+track()+cart(200+12*m.x,320,2)+L(200+12*m.x,210,200+12*m.x,340,'coral',2)+L(200+12*m.x2,210,200+12*m.x2,340,'aqua',2)+A(200+12*m.x,190,200+12*m.x2,190,'aqua')+vec(200+12*m.x,290,m.v,0,10,'coral','v now')+info([`Δt = ${s.window} s`,`gate spacing = ${f(m.x2-m.x)} m`,`v_now = ${f(m.v)} m/s`],740,100)+note('First gate follows model time; second gate samples the future. Fixed 12 px/m scale.'),[step('Follow the position rule','Position gives where the cart is, but velocity asks how quickly that position changes.','x(t) = ut + bt²','The cart and first gate move together.'),step('Measure a finite interval','The two gates record a displacement during Δt. For acceleration, this differs from the starting velocity.','v_avg = [x(t+Δt) − x(t)]/Δt','The aqua gate is farther forward when the interval is larger.'),step('Take the local limit','Shrinking Δt removes the extra average contribution bΔt.','v(t) = dx/dt = u + 2bt','The two-gate reading approaches the coral instantaneous velocity.')],(s,m)=>{let t=Number(f(s.time)),v=s.u+2*s.b*t;return target(`At t=${f(t)} s, x=(${s.u})t+(${s.b})t² meters. Find instantaneous velocity.`,v,'m/s',[`Differentiate x(t): v = ${s.u} + 2(${s.b})t`,`At t=${f(t)}, v = ${f(v)} m/s`]);},physical(5),[6,7],'§2.2 derivative limit v=dx/dt; forward finite-interval velocity differs by bΔt.');

def('2.3','Watch velocity change on a powered cart','The motor acceleration itself increases at a fixed rate. The velocity arrow can change length and reverse even while the cart is still moving in its earlier direction.',[N('u','Initial velocity',-3,3,1,-2,'m/s'),N('a0','Initial acceleration',-1,1,.5,.5,'m/s²'),N('jerk','Acceleration increase per second',0,.8,.1,.4,'m/s³')],s=>{let t=s.time;return{x:s.u*t+s.a0*t*t/2+s.jerk*t**3/6,v:s.u+s.a0*t+s.jerk*t*t/2,a:s.a0+s.jerk*t,readouts:[r('Velocity',s.u+s.a0*t+s.jerk*t*t/2,'m/s'),r('Acceleration',s.a0+s.jerk*t,'m/s²')]};},(s,m)=>head('Acceleration changes velocity, not directly position')+track()+cart(200+12*m.x,320,2,'powered cart')+vec(200+12*m.x,250,m.v,0,8,'coral','velocity')+vec(200+12*m.x,180,m.a,0,18,'aqua','acceleration')+info([`a(t) = ${f(m.a)} m/s²`,`v(t) = ${f(m.v)} m/s`,`x(t) = ${f(m.x)} m`],740,100)+note('Signed arrows: right is positive. Arrow scales are 8 px/(m/s) and 18 px/(m/s²).'),[step('Separate velocity from acceleration','A positive acceleration can slow a cart that initially moves left.','a = dv/dt','Compare the direction of the coral and aqua arrows.'),step('Allow acceleration to change','This motor ramps acceleration with constant jerk j; constant-acceleration formulas would be wrong.','a(t) = a₀ + jt','The aqua acceleration arrow grows according to the ramp control.'),step('Accumulate velocity changes','Integrating acceleration adds both a linear and a quadratic velocity contribution.','v(t) = u + a₀t + ½jt²','The velocity arrow reverses only after the leftward velocity has been cancelled.')],(s,m)=>{let t=Number(f(s.time)),a=s.a0+s.jerk*t;return target(`At t=${f(t)} s, a(t)=${s.a0}+${s.jerk}t m/s². Find instantaneous acceleration.`,a,'m/s²',[`a(t) = a₀ + jt`,`a = ${s.a0} + (${s.jerk})(${f(t)}) = ${f(a)} m/s²`]);},physical(2.5),[8,9,10],'§2.3 a=dv/dt; original polynomial motion illustrates changing acceleration.');

def('2.4','Accelerate a cart along a fixed ruler','The drive applies constant acceleration. Compare the initial velocity contribution with the extra distance accumulated as the velocity changes.',[N('x0','Initial position',-3,3,1,0,'m'),N('u','Initial velocity',-2,4,1,2,'m/s'),N('a','Constant acceleration',-1,2,.25,1,'m/s²')],s=>({x:s.x0+s.u*s.time+.5*s.a*s.time**2,v:s.u+s.a*s.time,readouts:[r('Position',s.x0+s.u*s.time+.5*s.a*s.time**2,'m'),r('Velocity',s.u+s.a*s.time,'m/s')]}),(s,m)=>head('Equal times add equal changes of velocity')+track()+cart(200+12*m.x,320,2)+vec(200+12*m.x,260,m.v,0,9,'coral','v')+vec(200+12*m.x,190,s.a,0,25,'aqua','a')+C(200+12*s.x0,320,5,'line')+info([`x₀ = ${s.x0} m`,`x = ${f(m.x)} m`,`v = ${f(m.v)} m/s`],740,100)+note('Air track: acceleration constant, no hidden friction; fixed spatial scale.'),[step('Start with the initial state','Initial velocity is present before the drive changes it.','v(0) = u; x(0) = x₀','The small gray marker records the starting point.'),step('Accumulate a constant acceleration','Every second adds the same velocity increment.','v = u + at','The aqua arrow stays fixed while the coral velocity arrow changes.'),step('Use the average velocity','For constant acceleration, the average of initial and final velocity gives displacement.','x = x₀ + ut + ½at²','The cart position includes both the initial drift and changing-speed contribution.')],(s,m)=>{let t=Number(f(s.time)),x=s.x0+s.u*t+.5*s.a*t*t;return target(`At t=${f(t)} s, x₀=${s.x0} m, u=${s.u} m/s and a=${s.a} m/s². Find position.`,x,'m',[`x = x₀ + ut + ½at²`,`x = ${s.x0} + (${s.u})(${f(t)}) + ½(${s.a})(${f(t)})² = ${f(x)} m`]);},physical(2.5),[11,12,13,14],'§2.4 constant-acceleration equations, Table2-1.');

def('2.5','Launch and catch a freely falling ball','Release a ball with an upward or downward initial velocity. Gravity continues downward even at the highest point, where the velocity is momentarily zero.',[N('height','Release height',2,12,1,8,'m'),N('u','Initial upward velocity',-4,8,1,4,'m/s'),N('gravity','Downward gravity g',3,12,.2,9.8,'m/s²')],s=>{let hit=(s.u+Math.sqrt(s.u*s.u+2*s.gravity*s.height))/s.gravity,t=Math.min(s.time,hit);return{t,hit,y:Math.max(0,s.height+s.u*t-.5*s.gravity*t*t),v:s.u-s.gravity*t,readouts:[r('Height above ground',Math.max(0,s.height+s.u*t-.5*s.gravity*t*t),'m'),r('Upward velocity',s.u-s.gravity*t,'m/s'),r('Impact time',hit,'s')]};},(s,m)=>head('Upward velocity does not mean upward acceleration')+L(100,400,820,400,'wire',4)+ball(350,400-12*m.y)+vec(350,400-12*m.y,m.v===0?0:0,m.v,3,'coral','v')+vec(420,400-12*m.y,0,-s.gravity,4,'aqua','g')+L(220,400,220,400-12*s.height,'line',2)+info([`y = ${f(m.y)} m`,`v_y = ${f(m.v)} m/s`,s.time>=m.hit?'Clock stops at first ground contact':'Air resistance neglected'],740,110)+note('Height: 12 px/m. Free-flight clock freezes at impact; collision behavior is not modeled.'),[step('Choose an upward coordinate','Gravity points downward, so its acceleration is negative in an upward coordinate.','a_y = −g','The aqua acceleration arrow always points downward.'),step('Follow height and velocity','The velocity changes linearly while position changes quadratically.','y = h + ut − ½gt²; v_y = u − gt','Scrub to the highest point: v_y=0 while gravity remains nonzero.'),step('End free flight at the ground','The positive root of y(t)=0 gives first ground contact.','t_hit = [u + √(u²+2gh)]/g','The display holds the instant just before contact.')],(s,m)=>target(`A ball starts ${s.height} m high with upward speed ${s.u} m/s and g=${s.gravity} m/s². Find first ground-contact time.`,m.hit,'s',[`Set 0 = h + ut − ½gt²`,`Positive root: (${s.u} + √(${s.u}² + 2×${s.gravity}×${s.height}))/${s.gravity} = ${f(m.hit)} s`]),physical(7),[15,16],'§2.5 free-fall equations; ground event terminates the model, no rebound.');

def('2.6','Build motion from two thrust intervals','A cart receives one constant acceleration for two seconds and another for the next two. Colored velocity-change tiles show how signed contributions accumulate.',[N('first','Acceleration during 0–2 s',-1,2,.5,1,'m/s²'),N('second','Acceleration during 2–4 s',-1,2,.5,-.5,'m/s²'),N('u','Starting velocity',0,4,1,2,'m/s')],s=>{let t=s.time,p=Math.min(t,2),q=Math.max(0,t-2),v=s.u+s.first*p+s.second*q,x=s.u*p+.5*s.first*p*p+(s.u+2*s.first)*q+.5*s.second*q*q;return{x,v,p,q,readouts:[r('Accumulated Δv',v-s.u,'m/s'),r('Velocity',v,'m/s'),r('Displacement',x,'m')]};},(s,m)=>{let q=head('Accumulate signed changes, then accumulate travel')+track()+cart(200+12*m.x,320,2,'two-stage drive')+vec(200+12*m.x,265,m.v,0,10,'coral','v');let w1=60*Math.abs(s.first*m.p),w2=60*Math.abs(s.second*m.q);q+=R(130,100,w1,30,s.first<0?'aqua':'coral',2)+R(130,145,w2,30,s.second<0?'aqua':'coral',2)+T(520,122,`first Δv = ${f(s.first*m.p)} m/s`,16)+T(520,167,`second Δv = ${f(s.second*m.q)} m/s`,16);return q+note('Tiles measure signed acceleration × elapsed time. Model time switches the drive at t=2 s.');},[step('Accumulate acceleration','The integral of acceleration is a signed velocity change, including negative contributions.','Δv = ∫a dt','Coral tiles add positive velocity; aqua tiles add negative velocity.'),step('Carry velocity between intervals','The second interval starts with the first interval’s final velocity.','v(2) = u + 2a₁','The drive switches at two seconds without jumping the cart’s velocity.'),step('Accumulate displacement','Integrating velocity gives displacement. For each constant-acceleration interval, use its own starting velocity.','Δx = Σ[v_start Δt + ½a(Δt)²]','The cart location responds to both intervals, even when their net Δv cancels.')],(s,m)=>target(`After the full 4 s, initial velocity is ${s.u} m/s; a₁=${s.first} m/s² for 2 s and a₂=${s.second} m/s² for 2 s. Find final velocity.`,s.u+2*s.first+2*s.second,'m/s',[`Δv₁ = 2(${s.first}); Δv₂ = 2(${s.second}) m/s`,`v(4) = ${s.u}+${2*s.first}+${2*s.second} = ${f(s.u+2*s.first+2*s.second)} m/s`]),physical(4),[17,18],'§2.6 graphical integration recast as signed acceleration-time tiles and real cart, no primary graph.');

def('3.1','Resolve a displacement arrow into components','Rotate and resize a real displacement arrow. Its horizontal and vertical projections form a right triangle; signed components record direction.',[N('length','Vector magnitude',1,6,.5,4,'m'),N('angle','Angle from +x',-150,150,15,45,'°')],s=>({x:s.length*Math.cos(rad(s.angle)),y:s.length*Math.sin(rad(s.angle)),readouts:[r('Horizontal component',s.length*Math.cos(rad(s.angle)),'m'),r('Vertical component',s.length*Math.sin(rad(s.angle)),'m')]}),(s,m,t)=>head('One vector, two signed projections')+L(90,300,610,300,'line',1)+L(340,80,340,435,'line',1)+A(340,300,340+35*m.x,300-35*m.y,'coral',5)+A(340,300,340+35*m.x,300,'aqua')+A(340+35*m.x,300,340+35*m.x,300-35*m.y,'aqua')+C(340+35*m.x*Math.min(t/8,1),300-35*m.y*Math.min(t/8,1),5,'paper')+info([`aₓ = ${f(m.x)} m`,`aᵧ = ${f(m.y)} m`,`|a| = ${s.length} m`,`θ = ${s.angle}°`])+note('Fixed scale: 35 px/m. Angle is measured counterclockwise from the rightward direction.'),[step('Keep magnitude separate from direction','The arrow length measures magnitude; rotation changes direction without changing that length.','|a| = √(aₓ²+aᵧ²)','Turn the coral vector while watching its length stay fixed.'),step('Project horizontally','The adjacent side of the component triangle is the magnitude times cosine.','aₓ = |a| cos θ','The horizontal aqua arrow can point left when the component is negative.'),step('Project vertically','The opposite side is the magnitude times sine.','aᵧ = |a| sin θ','The vertical aqua arrow points down for a negative y component.')],(s,m)=>target(`For magnitude ${s.length} m and θ=${s.angle}° from +x, find the signed horizontal component.`,m.x,'m',[`aₓ = |a| cos θ`,`aₓ = ${s.length} cos(${s.angle}°) = ${f(m.x)} m`]),staged(),[1,2,3,4],'§3.1 head-to-tail addition, signed component projection; original vector triangle.');

def('3.2','Assemble two displacement arrows head to tail','Move a second displacement to the head of the first without rotating it. The resultant joins the original tail to the final head.',[N('ax','First vector x component',-4,4,1,3,'m'),N('bx','Second vector x component',-4,4,1,-1,'m'),N('by','Second vector y component',-4,4,1,3,'m')],s=>({x:s.ax+s.bx,y:1+s.by,length:Math.hypot(s.ax+s.bx,1+s.by),readouts:[r('Resultant x',s.ax+s.bx,'m'),r('Resultant y',1+s.by,'m'),r('Resultant magnitude',Math.hypot(s.ax+s.bx,1+s.by),'m')]}),(s,m,t)=>{let p=Math.min(t/8,1),ox=350,oy=310,bx=ox+30*s.ax*p,by=oy-30*p;return head('Add matching components independently')+L(80,310,640,310,'line',1)+L(350,100,350,440,'line',1)+A(ox,oy,ox+30*s.ax,oy-30,'coral',4)+A(bx,by,bx+30*s.bx,by-30*s.by,'aqua',4)+A(ox,oy,ox+30*m.x,oy-30*m.y,'wire',3)+info([`a = (${s.ax}, 1) m`,`b = (${s.bx}, ${s.by}) m`,`r = (${m.x}, ${m.y}) m`,`|r| = ${f(m.length)} m`])+note('The aqua arrow is translated, never rotated; its displacement does not depend on where it is drawn.');},[step('Write unit-vector components','Components describe the displacement along independent coordinate directions.','a = aₓî + 1ĵ; b = bₓî + bᵧĵ','The two arrows keep their individual directions during placement.'),step('Place the second arrow','Translation of a free vector preserves its magnitude and orientation.','r = a + b','Run the assembly to move the aqua tail to the coral head.'),step('Add like components','Independent x and y contributions sum separately.','rₓ = aₓ+bₓ; rᵧ = 1+bᵧ','The dark resultant always reaches the final head.')],(s,m)=>target(`For a=(${s.ax},1) m and b=(${s.bx},${s.by}) m, find |a+b|.`,m.length,'m',[`r = (${m.x},${m.y}) m`,`|r| = √(${m.x}² + ${m.y}²) = ${f(m.length)} m`]),staged(),[7,8,9],'§3.2 unit vectors and component sums. During construction only, aqua arrow is not yet head-to-tail.');

def('3.3','Compare scalar and vector products','Two arrows share a tail. The dot-product view projects one onto the other; the cross-product view builds their parallelogram and marks its perpendicular direction.',[N('a','First magnitude',1,4,.5,3),N('b','Second magnitude',1,4,.5,2),N('angle','Signed angle from a to b',-150,150,15,60,'°'),O('product','Product view','dot',[['dot','Dot product: projection'],['cross','Cross product: area and direction']])],s=>({bx:s.b*Math.cos(rad(s.angle)),by:s.b*Math.sin(rad(s.angle)),dot:s.a*s.b*Math.cos(rad(s.angle)),cross:s.a*s.b*Math.sin(rad(s.angle)),readouts:[r('a · b',s.a*s.b*Math.cos(rad(s.angle))),r('Signed z component of a × b',s.a*s.b*Math.sin(rad(s.angle)))]}),(s,m,t)=>{let x=260,y=320,sc=40,q=head('Projection and oriented area answer different questions')+A(x,y,x+sc*s.a,y,'coral',4)+A(x,y,x+sc*m.bx,y-sc*m.by,'aqua',4);if(s.product==='dot'){q+=L(x+sc*m.bx,y-sc*m.by,x+sc*m.bx,y,'line',2)+A(x,y+35,x+sc*m.bx,y+35,'wire',4);}else{q+=P(`M${x},${y}L${x+sc*s.a},${y}L${x+sc*(s.a+m.bx)},${y-sc*m.by}L${x+sc*m.bx},${y-sc*m.by}Z`,'line',2,'surface')+A(x,y,x+sc*s.a,y,'coral',4)+A(x,y,x+sc*m.bx,y-sc*m.by,'aqua',4)+C(560,250,24,'surface')+(m.cross>=0?C(560,250,6,'coral'):L(548,238,572,262,'coral',3)+L(572,238,548,262,'coral',3))+T(560,300,m.cross>=0?'out of page':'into page',15);}q+=C(x+sc*m.bx*Math.min(t/8,1),y-sc*m.by*Math.min(t/8,1),4,'paper');return q+info([`a · b = ${f(m.dot)}`,`(a × b)z = ${f(m.cross)}`,s.product==='dot'?'Signed projection → scalar':'Area + right-hand direction'],755,120)+note('a points right; positive signed angle turns counterclockwise. Dot/cross values use arbitrary consistent units.');},[step('Project for a scalar','The dot product measures alignment. Perpendicular vectors have zero dot product.','a · b = ab cos θ','In projection view, the lower arrow is the signed component of b along a.'),step('Build an area','The cross-product magnitude equals the base times perpendicular height.','|a × b| = ab |sin θ|','The parallelogram collapses when the arrows are parallel.'),step('Use the right-hand rule','The cross product has a direction perpendicular to the original plane. Reversing the angle reverses that direction.','(a × b)z = ab sin θ','A dot means out of the page; a cross means into the page.')],(s,m)=>target(`For a=${s.a}, b=${s.b}, and signed θ=${s.angle}°, find ${s.product==='dot'?'a · b':'the signed z component of a × b'}.`,s.product==='dot'?m.dot:m.cross,'',[`${s.product==='dot'?'a · b = ab cos θ':'(a × b)z = ab sin θ'}`,`Result = ${f(s.product==='dot'?m.dot:m.cross)}`]),staged(),[11,12,13,14],'§3.3 dot product, parallelogram area, right-hand rule. Cross-product view retains signed orientation.');

def('4.1','Locate a rover with position vectors','Move the final location on a map. Position vectors start at the origin; displacement starts at the initial location and reaches the final location.',[N('x','Final east coordinate',-4,6,1,4,'m'),N('y','Final north coordinate',-3,5,1,3,'m')],s=>({dx:s.x+2,dy:s.y+1,length:Math.hypot(s.x+2,s.y+1),readouts:[r('East displacement',s.x+2,'m'),r('North displacement',s.y+1,'m'),r('Displacement magnitude',Math.hypot(s.x+2,s.y+1),'m')]}),(s,m,t)=>{let o=[340,310],a=[260,350],b=[340+40*s.x,310-40*s.y],p=Math.min(t/8,1);return head('A position belongs to the origin; displacement belongs to two events')+L(110,310,620,310,'line',1)+L(340,85,340,440,'line',1)+A(...o,...a,'line',3)+A(...o,...b,'coral',4)+A(...a,...b,'aqua',3)+cart(a[0]+(b[0]-a[0])*p,a[1]+(b[1]-a[1])*p,1,'rover')+T(260,395,'initial (−2, −1) m',15)+info([`final = (${s.x}, ${s.y}) m`,`Δr = (${m.dx}, ${m.dy}) m`,`|Δr| = ${f(m.length)} m`])+note('Map has a fixed 40 px/m scale. Rover motion is an endpoint construction, not specified dynamics.');},[step('Locate from an origin','A position vector locates one point relative to a chosen origin.','r = xî + yĵ','The coral position arrow starts where the map lines cross.'),step('Subtract positions','Displacement points from the initial location to the final location.','Δr = r_f − r_i','The aqua arrow starts at (−2,−1), not at the origin.'),step('Combine perpendicular components','Euclidean distance between the two events follows the component triangle.','|Δr| = √[(Δx)²+(Δy)²]','Changing one map coordinate changes only its matching component.')],(s,m)=>target(`A rover goes from (−2,−1) m to (${s.x},${s.y}) m. Find displacement magnitude.`,m.length,'m',[`Δr = (${s.x}−(−2), ${s.y}−(−1)) = (${m.dx},${m.dy}) m`,`|Δr| = √(${m.dx}²+${m.dy}²) = ${f(m.length)} m`]),staged(),[1,2],'§4.1 position/displacement vectors; original two-dimensional map.');

def('4.2','Follow a curved rover with a tangent velocity','A rover follows x=ut and y=bt². Its direction changes even though its eastward velocity stays constant; the arrow always points along its instantaneous motion.',[N('u','Eastward speed',1,4,.5,2,'m/s'),N('b','North-position coefficient',-.2,.5,.1,.2,'m/s²')],s=>({x:s.u*s.time,y:s.b*s.time**2,vx:s.u,vy:2*s.b*s.time,speed:Math.hypot(s.u,2*s.b*s.time),readouts:[r('East velocity',s.u,'m/s'),r('North velocity',2*s.b*s.time,'m/s'),r('Speed',Math.hypot(s.u,2*s.b*s.time),'m/s')]}),(s,m,t)=>{let q=head('Velocity is tangent to a curved path'),d='';for(let i=0;i<=50;i++){let tt=5*i/50;d+=`${i?'L':'M'}${130+22*s.u*tt},${330-15*s.b*tt*tt}`;}return q+P(d,'line',2)+cart(130+22*m.x,330-15*m.y,1,'rover')+A(130+22*m.x,300-15*m.y,130+22*m.x+22*m.vx,300-15*m.y-15*m.vy,'coral',4)+info([`vₓ = ${f(m.vx)} m/s`,`vᵧ = ${f(m.vy)} m/s`,`speed = ${f(m.speed)} m/s`])+note('Map scale: 22 px/m east and 15 px/m north. Velocity arrow shows one second of tangent displacement.');},[step('Differentiate coordinates separately','The position vector has independent component functions.','r(t) = ut î + bt² ĵ','The rover’s curved trail comes directly from its two coordinates.'),step('Find a vector velocity','Velocity is the derivative of position and points tangent to the path.','v = u î + 2bt ĵ','The coral arrow turns as its northward component changes.'),step('Distinguish speed from a component','Speed is the magnitude of the full velocity vector.','speed = √[u²+(2bt)²]','The speed can increase while the eastward component remains fixed.')],(s,m)=>{let t=Number(f(s.time)),vy=2*s.b*t,v=Math.hypot(s.u,vy);return target(`At t=${f(t)} s, x=${s.u}t and y=${s.b}t² meters. Find the speed.`,v,'m/s',[`vₓ=${s.u}; vᵧ=2(${s.b})(${f(t)})=${f(vy)} m/s`,`speed = √(vₓ²+vᵧ²) = ${f(v)} m/s`]);},physical(5),[3,4,5],'§4.2 vector derivative and speed; unequal map scales explicitly labeled, not a physical angle gauge.');

def('4.3','Steer a puck with two acceleration components','Two independent thrusters accelerate a puck east and north. Compare the velocity gained with the constant acceleration vector producing it.',[N('ax','East acceleration',-1,1,.25,.5,'m/s²'),N('ay','North acceleration',-1,1,.25,.5,'m/s²')],s=>({x:2*s.time+.5*s.ax*s.time**2,y:.5*s.ay*s.time**2,vx:2+s.ax*s.time,vy:s.ay*s.time,amag:Math.hypot(s.ax,s.ay),readouts:[r('East velocity',2+s.ax*s.time,'m/s'),r('North velocity',s.ay*s.time,'m/s'),r('Acceleration magnitude',Math.hypot(s.ax,s.ay),'m/s²')]}),(s,m)=>head('The change of velocity points along acceleration')+R(90,90,560,350,'surface',10)+ball(180+22*m.x,290-16*m.y)+vec(180+22*m.x,260-16*m.y,m.vx,m.vy,15,'coral','v')+vec(180+22*m.x,290-16*m.y,s.ax,s.ay,40,'aqua','a')+A(730,300,790,300,'line',3)+A(730,300,730+30*m.vx,300-30*m.vy,'coral',3)+A(790,300,730+30*m.vx,300-30*m.vy,'aqua',3)+T(780,375,'velocity-change triangle',15)+note('Puck starts at 2 m/s east, zero north. Position scales 22 px/m east,16 px/m north; vector arrows use equal scales.'),[step('Use both coordinate equations','Acceleration is a vector; independent thrusters control its independent components.','a = aₓî + aᵧĵ','Changing one thrust changes only its corresponding acceleration component.'),step('Accumulate the velocity change','For constant vector acceleration, the velocity change is parallel to acceleration.','Δv = a Δt','The aqua side of the right-hand triangle joins initial velocity to current velocity.'),step('Update position consistently','Each position component follows its own constant-acceleration equation.','r(t) = r₀ + v₀t + ½at²','The puck path follows the same acceleration used by its velocity triangle.')],(s,m)=>target(`The puck has constant acceleration (${s.ax},${s.ay}) m/s². Find acceleration magnitude.`,m.amag,'m/s²',[`|a|=√(aₓ²+aᵧ²)`,`|a|=√(${s.ax}²+${s.ay}²)=${f(m.amag)} m/s²`]),physical(4),[6,7,8],'§4.3 vector acceleration and constant component equations. Velocity triangle is separate from unequal-scale position map.');

def('4.4','Launch a projectile across a field','Aim the launcher and watch independent horizontal drift and vertical fall combine into one flight. The acceleration remains downward throughout.',[N('speed','Launch speed',5,16,1,12,'m/s'),N('angle','Launch elevation',20,75,5,45,'°'),N('gravity','Gravity g',5,15,.2,9.8,'m/s²')],s=>{let ux=s.speed*Math.cos(rad(s.angle)),uy=s.speed*Math.sin(rad(s.angle)),flight=2*uy/s.gravity,t=Math.min(s.time,flight);return{ux,uy,flight,t,x:ux*t,y:Math.max(0,uy*t-.5*s.gravity*t*t),vy:uy-s.gravity*t,range:ux*flight,readouts:[r('Height',Math.max(0,uy*t-.5*s.gravity*t*t),'m'),r('Horizontal velocity',ux,'m/s'),r('Vertical velocity',uy-s.gravity*t,'m/s'),r('Full range',ux*flight,'m')]};},(s,m,t)=>{let q=head('Horizontal motion and vertical free fall share one clock')+L(80,385,870,385,'wire',4)+L(100,385,100+45*Math.cos(rad(s.angle)),385-45*Math.sin(rad(s.angle)),'aqua',9),d='';for(let i=0;i<=70;i++){let tt=m.flight*i/70;d+=`${i?'L':'M'}${100+10*m.ux*tt},${385-10*(m.uy*tt-.5*s.gravity*tt*tt)}`;}q+=P(d,'line',2)+ball(100+10*m.x,385-10*m.y)+vec(100+10*m.x,385-10*m.y,m.ux,m.vy,5,'coral','v')+vec(180+10*m.x,385-10*m.y,0,-s.gravity,3,'aqua','g');return q+info([`t_flight = ${f(m.flight)} s`,`range = ${f(m.range)} m`,`vₓ remains ${f(m.ux)} m/s`],730,110)+note('Equal scale 10 px/m. Same launch/landing height, no air resistance; clock freezes just before landing.');},[step('Resolve launch velocity','One launch vector provides independent horizontal and vertical starting velocities.','uₓ = u cos θ; uᵧ = u sin θ','The launcher angle changes both velocity components.'),step('Apply gravity vertically','Without drag there is no horizontal force. Gravity changes only the vertical component.','x=uₓt; y=uᵧt−½gt²','The coral arrow bends downward while the aqua acceleration stays vertical.'),step('Find the landing event','At the original height, the nonzero solution of y=0 is twice the time to the top.','T=2uᵧ/g; R=uₓT','The full trail ends exactly where the ball returns to the launch height.')],(s,m)=>target(`For launch speed ${s.speed} m/s, angle ${s.angle}°, g=${s.gravity} m/s², and equal landing height, find range.`,m.range,'m',[`uₓ=${f(m.ux)}; uᵧ=${f(m.uy)} m/s`,`T=2uᵧ/g=${f(m.flight)} s`,`R=uₓT=${f(m.range)} m`]),physical(7),[9,10,11,12,13],'§4.4 ideal projectile motion. Original launcher, exact equal-height flight termination.');

function circularScene(s,m,t,force=false){let cx=340,cy=275,rr=s.radius*50,a=s.speed*t/s.radius,x=cx+rr*Math.cos(a),y=cy-rr*Math.sin(a),q=head(force?'The inward net force continually turns the velocity':'Constant speed can still mean changing velocity')+P(`M${cx+rr},${cy} A${rr},${rr} 0 1 0 ${cx-rr},${cy} A${rr},${rr} 0 1 0 ${cx+rr},${cy}`,'line',3)+L(cx,cy,x,y,'line',2)+ball(x,y,s.mass||2)+vec(x,y,-s.speed*Math.sin(a),s.speed*Math.cos(a),9,'coral','v');q+=vec(x,y,-Math.cos(a)*(force?m.force:m.accel),-Math.sin(a)*(force?m.force:m.accel),force?.55:3,'aqua',force?'F net':'a');return q+info([`r = ${s.radius} m`,`speed = ${s.speed} m/s`,`a = ${f(m.accel)} m/s²`,force?`F = ${f(m.force)} N`:`period = ${f(m.period)} s`])+note(force?'Equal radius scale 50 px/m. Inward arrow is the resultant of real forces, not an additional force.':'Equal radius scale 50 px/m; velocity tangent, acceleration radial. Arrow scales are fixed.');}
def('4.5','Drive a bead around a circular guide','Change the orbit radius and speed. The velocity is tangent to the guide while the acceleration always points toward its center.',[N('radius','Guide radius',1,3,.5,2,'m'),N('speed','Constant speed',1,6,.5,3,'m/s')],s=>({accel:s.speed*s.speed/s.radius,period:2*pi*s.radius/s.speed,readouts:[r('Centripetal acceleration',s.speed*s.speed/s.radius,'m/s²'),r('Period',2*pi*s.radius/s.speed,'s')]}),(s,m,t)=>circularScene(s,m,t),[step('Hold speed constant','Uniform circular motion keeps the magnitude of velocity constant, not its direction.','|v| = constant','The velocity arrow stays tangent to the bead’s circular guide.'),step('Turn the velocity vector','Changing direction requires acceleration even without changing speed.','a = v²/r','The aqua arrow always points toward the center.'),step('Relate one lap to time','The distance traveled in a lap is the circumference.','T = 2πr/v','A larger guide takes longer per lap at the same speed.')],(s,m)=>target(`A bead moves at ${s.speed} m/s on a radius-${s.radius} m guide. Find acceleration magnitude.`,m.accel,'m/s²',[`a=v²/r`,`a=${s.speed}²/${s.radius}=${f(m.accel)} m/s²`]),physical(12),[15,16,17],'§4.5 uniform circular kinematics, tangential velocity, inward acceleration.');

def('4.6','Walk through a moving train','Watch the same walker from the station or from the train. Relative velocities add with their signs; switching observer changes the displayed motion of the surroundings.',[N('train','Train velocity relative to ground',-4,4,.5,3,'m/s'),N('walk','Walker velocity relative to train',-2,2,.5,1,'m/s'),O('frame','Observe from','ground',[['ground','Station platform'],['train','Train carriage']])],s=>({ground:s.train+s.walk,base:s.frame==='ground'?s.train*s.time:0,person:s.frame==='ground'?(s.train+s.walk)*s.time:s.walk*s.time,station:s.frame==='ground'?0:-s.train*s.time,readouts:[r('Walker relative to ground',s.train+s.walk,'m/s'),r('Walker relative to train',s.walk,'m/s'),r('Displayed walker velocity',s.frame==='ground'?s.train+s.walk:s.walk,'m/s')]}),(s,m,t)=>{let bx=440+10*m.base,px=440+10*m.person,station=440+10*m.station;return head('Velocity belongs to an object AND an observer')+rail(405)+R(bx-165,190,330,150,'surface',8)+R(bx-145,210,280,80,'paper',4)+C(px,240,12,'coral')+L(px,253,px,292,'coral',5)+L(px,292,px-14,315,'coral',4)+L(px,292,px+14,315,'coral',4)+R(station-28,360,56,40,'aqua')+T(station,390,'station',12)+vec(px,168,s.frame==='ground'?s.train+s.walk:s.walk,0,18,'coral','walker velocity')+info([`v_train/ground = ${s.train}`,`v_walker/train = ${s.walk}`,`v_walker/ground = ${f(m.ground)}`],750,80)+note('10 px/m fixed scale. Velocities are constant; switching frames changes both train and station motion.');},[step('Name both frames','A velocity statement needs both the moving object and the observer.','v_P/A = walker relative to ground','Choose the station or carriage observer.'),step('Add signed velocities','A walker moving against the train has a negative relative velocity.','v_P/A = v_P/B + v_B/A','The walker’s ground speed is the sum of walking and train velocities.'),step('Change the observer','The same event has different coordinates in the two inertial frames, but constant relative frame speed adds no acceleration.','x_P/B = x_P/A − x_B/A','In the carriage frame the train stays still and the station moves backward.')],(s,m)=>target(`Train velocity is ${s.train} m/s relative to ground; walking velocity is ${s.walk} m/s relative to train. Find walker velocity relative to ground.`,m.ground,'m/s',[`v_walker/ground = v_walker/train + v_train/ground`,`v = ${s.walk} + (${s.train}) = ${f(m.ground)} m/s`]),physical(5),[17,18],'§4.6 Galilean velocity addition for inertial observers; original train apparatus.');

def('4.7','Pilot a boat across a flowing river','The boat points straight across the water. The current carries it sideways while its own engine supplies the cross-river velocity.',[N('boat','Boat speed relative to water',2,6,.5,3,'m/s'),N('current','Current eastward speed',-2,2,.5,1,'m/s'),N('width','River width',10,30,5,20,'m')],s=>{let crossing=s.width/s.boat,t=Math.min(s.time,crossing);return{crossing,t,x:s.current*t,y:s.boat*t,drift:s.current*crossing,speed:Math.hypot(s.boat,s.current),readouts:[r('Time to opposite bank',crossing,'s'),r('Eastward landing drift',s.current*crossing,'m'),r('Ground speed',Math.hypot(s.boat,s.current),'m/s')]};},(s,m,t)=>{let top=420-10*s.width,x=360+10*m.x,y=420-10*m.y,q=head('Water-relative and ground-relative velocities differ')+R(70,top,600,420-top,'surface',2)+L(70,420,670,420,'wire',5)+L(70,top,670,top,'wire',5);for(let yy=top+35;yy<420;yy+=55)q+=A(120,yy,120+35*s.current,yy,'aqua',3);q+=P(`M${x},${y-18}L${x-12},${y+16}L${x+12},${y+16}Z`,'coral',2,'coral')+A(x,y,x,y-7*s.boat,'aqua')+A(x,y-7*s.boat,x+7*s.current,y-7*s.boat,'line')+A(x,y,x+7*s.current,y-7*s.boat,'coral',3)+L(360,420,360+10*m.drift,top,'line',2);return q+info([`crossing = ${f(m.crossing)} s`,`landing drift = ${f(m.drift)} m`,`ground speed = ${f(m.speed)} m/s`],790,130)+note('Equal map scale 10 px/m; velocity arrows 7 px/(m/s). Bow points north; current is uniform; clock freezes on the opposite bank.');},[step('Separate frames','Boat speed through water is not its speed over the riverbed.','v_boat/ground = v_boat/water + v_water/ground','The northward aqua vector and sideways current add to the coral ground vector.'),step('Use the crossing component','Only the northward component closes the distance to the other bank.','T = width/v_boat/water','Changing the current shifts the landing point without changing crossing time.'),step('Accumulate drift','Current acts for the full crossing time.','drift = v_current T','The slanted path ends downstream for positive current, upstream for negative current.')],(s,m)=>target(`Boat speed across water is ${s.boat} m/s, current is ${s.current} m/s east, river width ${s.width} m. Find eastward landing drift.`,m.drift,'m',[`T=${s.width}/${s.boat}=${f(m.crossing)} s`,`drift=${s.current}×${f(m.crossing)}=${f(m.drift)} m`]),physical(15),[19,20],'§4.7 two-dimensional relative velocity; original steady-current crossing experiment.');

def('5.1','Push an air-track cart from both sides','Two opposing forces act on the same cart. Only their vector sum produces acceleration; equal forces leave a moving cart unaccelerated.',[N('right','Rightward force',0,8,1,6,'N'),N('left','Leftward force',0,8,1,2,'N'),N('mass','Cart mass',1,5,1,2,'kg')],s=>{let force=s.right-s.left,a=force/s.mass;return{force,a,x:.5*a*s.time*s.time,v:a*s.time,readouts:[r('Net rightward force',force,'N'),r('Rightward acceleration',a,'m/s²'),r('Velocity',a*s.time,'m/s')]};},(s,m)=>head('Add forces before dividing by mass')+rail(370)+cart(440+8*m.x,340,s.mass,`${s.mass} kg`)+vec(440+8*m.x,290,s.right,0,10,'coral','right force')+vec(440+8*m.x,245,-s.left,0,10,'aqua','left force')+vec(440+8*m.x,180,m.v,0,3,'wire','velocity')+info([`F_net = ${f(m.force)} N`,`a = ${f(m.a)} m/s²`],740,95)+note('Cart starts from rest; horizontal air track. Gravity and normal cancel vertically. Position scale 8 px/m.'),[step('Identify the system','Both horizontal arrows act on this one cart. Their opposite directions must be retained.','F_net,x = F_right − F_left','The aqua arrow points left while the coral arrow points right.'),step('Apply Newton’s second law','Mass measures resistance to acceleration from a given net force.','aₓ = F_net,x/m','Increasing cart mass enlarges the cart and reduces its acceleration.'),step('Use the initial condition','With zero initial velocity, constant net force produces linearly increasing velocity.','vₓ=at; x−x₀=½at²','The cart does not move when both forces balance and its initial velocity is zero.')],(s,m)=>target(`Right force ${s.right} N, left force ${s.left} N, mass ${s.mass} kg. Find signed rightward acceleration.`,m.a,'m/s²',[`F_net=${s.right}−${s.left}=${m.force} N`,`a=${m.force}/${s.mass}=${f(m.a)} m/s²`]),physical(3),[1,2,3,4,5],'§5.1 first and second laws, vector net force; ideal horizontal air track.');

def('5.2','Read a scale inside an accelerating elevator','The scale measures the normal force, which equals mg only when vertical acceleration is zero. Change the elevator acceleration and compare the two forces.',[N('mass','Passenger mass',40,100,10,60,'kg'),N('a','Upward elevator acceleration',-3,3,1,1,'m/s²')],s=>({normal:s.mass*(g+s.a),weight:s.mass*g,y:.5*s.a*s.time*s.time,readouts:[r('Scale normal-force reading',s.mass*(g+s.a),'N'),r('Gravitational force magnitude',s.mass*g,'N'),r('Net upward force',s.mass*s.a,'N')]}),(s,m,t)=>{let y=290-8*m.y;return head('The scale reads contact force, not a change in gravity')+R(250,y-120,260,210,'surface',4)+R(310,y+40,140,28,'aqua',3)+T(380,y+61,`${f(m.normal)} N`,16,'paper')+C(380,y-60,16,'coral')+L(380,y-43,380,y+7,'coral',7)+L(380,y+7,355,y+39,'coral',6)+L(380,y+7,405,y+39,'coral',6)+vec(290,y-10,0,m.normal,.08,'aqua','N')+vec(470,y-10,0,-m.weight,.08,'coral','mg')+info([`a_up = ${s.a} m/s²`,`N = ${f(m.normal)} N`,`mg = ${f(m.weight)} N`],755,140)+note('Elevator and passenger have the same constant acceleration; scale remains in contact. Position 8 px/m.');},[step('Name the forces','The passenger has an upward normal force and a downward gravitational force.','ΣF_y = N − mg','The two force arrows belong to the passenger.'),step('Use the elevator acceleration','The passenger follows the elevator while contact is maintained.','N − mg = ma_y','Positive acceleration requires the upward force to exceed gravity.'),step('Interpret apparent weight','The scale responds to the normal force even though mass and local gravity stay fixed.','N = m(g+a_y)','Downward acceleration makes the scale read less than mg.')],(s,m)=>target(`For mass ${s.mass} kg and upward acceleration ${s.a} m/s², with g=9.8 m/s², find the scale force.`,m.normal,'N',[`N=m(g+a_y)`,`N=${s.mass}(9.8+(${s.a}))=${f(m.normal)} N`]),physical(2),[9,10,11,12],'§5.2 gravitational force, normal force and apparent weight; N remains positive throughout controls.');

def('5.3','Connect two masses over an ideal pulley','Release two masses joined by one light inextensible cord. They share an acceleration magnitude and one tension, while each mass obeys its own force equation.',[N('m1','Left mass',1,4,.5,3,'kg'),N('m2','Right mass',1,4,.5,2,'kg')],s=>{let a=g*(s.m1-s.m2)/(s.m1+s.m2),tension=2*s.m1*s.m2*g/(s.m1+s.m2);return{a,tension,drop:.5*a*s.time*s.time,readouts:[r('Left downward acceleration',a,'m/s²'),r('Cord tension',tension,'N'),r('Left downward displacement',.5*a*s.time*s.time,'m')]};},(s,m)=>{let y1=300+40*m.drop,y2=300-40*m.drop;return head('One cord couples two separate free-body equations')+C(380,140,70,'surface')+P('M310,140 A70,70 0 0 1 450,140','wire',4)+L(310,140,310,y1,'wire',3)+L(450,140,450,y2,'wire',3)+R(310-14*Math.sqrt(s.m1),y1,28*Math.sqrt(s.m1),38,'coral',3)+R(450-14*Math.sqrt(s.m2),y2,28*Math.sqrt(s.m2),38,'aqua',3)+T(310,y1+26,`${s.m1} kg`,14,'paper')+T(450,y2+26,`${s.m2} kg`,14,'paper')+vec(250,y1+18,0,-s.m1*g,.8,'coral','m₁g')+vec(510,y2+18,0,m.tension,.8,'aqua','T')+info([`a_left,down = ${f(m.a)} m/s²`,`T = ${f(m.tension)} N`,`cord length remains fixed`],750,140)+note('Massless cord and frictionless, massless pulley; motion shown only before either mass reaches a boundary.');},[step('Choose compatible coordinates','Take left-down and right-up as positive. The fixed cord makes their accelerations equal.','a₁,down = a₂,up = a','As one mass descends, the other rises by the same distance.'),step('Write one law per mass','Tension is internal to the two-mass system, but acts in each individual mass equation.','m₁g−T=m₁a; T−m₂g=m₂a','The same tension pulls both hanging masses upward.'),step('Eliminate the internal force','Adding the two equations cancels tension.','a=(m₁−m₂)g/(m₁+m₂)','Equal masses balance; exchanging them reverses motion.')],(s,m)=>target(`Ideal pulley with left ${s.m1} kg and right ${s.m2} kg; g=9.8 m/s². Find left-downward acceleration.`,m.a,'m/s²',[`(m₁−m₂)g=(m₁+m₂)a`,`a=(${s.m1}−${s.m2})9.8/(${s.m1}+${s.m2})=${f(m.a)} m/s²`]),physical(1),[13,14,15,16],'§5.3 applying Newton’s laws to connected bodies; original ideal Atwood machine.');

def('6.1','Test when friction yields to sliding','Increase the push on an initially resting block. Static friction matches it up to a limit; once sliding begins, the smaller kinetic friction governs acceleration.',[N('push','Applied rightward push',0,20,1,12,'N'),N('mass','Block mass',1,5,.5,2,'kg'),N('mu','Static friction coefficient μs',0,.8,.1,.5)],s=>{let limit=s.mu*s.mass*g,sliding=s.push>limit,friction=sliding?.8*limit:s.push,a=(s.push-friction)/s.mass;return{limit,sliding,friction,a,x:.5*a*s.time*s.time,readouts:[r('Static friction limit',limit,'N'),r('Actual opposing friction',friction,'N'),r('Rightward acceleration',a,'m/s²')]};},(s,m,t)=>{let x=240+8*m.x,q=head(m.sliding?'Sliding: kinetic friction is below the static limit':'Sticking: friction adjusts to the push')+rail(370)+R(x-28,300,56,60,'surface',3)+T(x,337,`${s.mass} kg`,14)+vec(x,270,s.push,0,8,'coral','push')+vec(x,215,-m.friction,0,8,'aqua','friction');for(let i=0;i<Math.round(s.mu*20);i++)q+=P(`M${110+i*30},370 l10,-8 l10,8`,'line',2);return q+info([`μs = ${s.mu}; μk = ${f(.8*s.mu)}`,`fs,max = ${f(m.limit)} N`,`friction = ${f(m.friction)} N`,`a = ${f(m.a)} m/s²`],750,95)+note('Each reset begins from rest; control edits re-solve that initial trial. μk=0.8μs; no friction-memory hysteresis.');},[step('Find the normal force','On a horizontal surface with no other vertical forces, the normal equals mg.','N=mg; f_s ≤ μ_sN','The roughness markers change with the friction coefficient.'),step('Test static equilibrium','Static friction is an adjusting force, not always its maximum value.','If F_push ≤ μ_sN: f_s = F_push','The block stays fixed while the two horizontal forces balance.'),step('Use kinetic friction after yield','Beyond the static limit, the initially resting trial begins sliding.','f_k=μ_kN; a=(F_push−f_k)/m','The block accelerates only after the applied push exceeds the threshold.')],(s,m)=>target(`An initially resting block has mass ${s.mass} kg, μs=${s.mu}, μk=${f(.8*s.mu)}, push=${s.push} N, g=9.8. Find rightward acceleration in this trial.`,m.a,'m/s²',[`Static limit = μsmg = ${f(m.limit)} N`,m.sliding?`Push exceeds limit: fk=${f(m.friction)} N; a=(F−fk)/m=${f(m.a)} m/s²`:'Push does not exceed the static limit; friction balances it and a=0.']),physical(2),[1,2,3,4],'§6.1 static/kinetic friction. Controls define new initially-resting trials, not a continuous stick-slip history.');

def('6.2','Drop a parachute through resisting air','The upward quadratic drag grows with speed until it balances gravity. Change the mass and canopy area to see both the transient and terminal speed.',[N('mass','Falling mass',1,5,.5,3,'kg'),N('area','Canopy effective area',.2,2,.2,1,'m²')],s=>{let b=.5*1.2*s.area,terminal=Math.sqrt(s.mass*g/b),u=g*s.time/terminal,v=terminal*Math.tanh(u),fall=terminal*terminal/g*Math.log(Math.cosh(u));return{b,terminal,v,fall,drag:b*v*v,readouts:[r('Downward speed',v,'m/s'),r('Terminal speed',terminal,'m/s'),r('Upward drag',b*v*v,'N'),r('Downward gravity',s.mass*g,'N')]};},(s,m,t)=>{let x=350,y=100+2.8*m.fall,rr=48*Math.sqrt(s.area),q=head('Drag grows with speed until the forces balance')+P(`M${x-rr},${y} Q${x},${y-rr} ${x+rr},${y}`,'aqua',4)+L(x-rr,y,x,y+35,'line',2)+L(x+rr,y,x,y+35,'line',2)+ball(x,y+43,s.mass)+vec(x-110,y+43,0,-s.mass*g,1.3,'coral','mg')+vec(x+110,y+43,0,m.drag,1.3,'aqua','drag');for(let i=0;i<6;i++){let yy=110+i*55-(t*22%55);q+=L(180,yy,180,yy-18,'line',2);}return q+info([`v = ${f(m.v)} m/s down`,`v_terminal = ${f(m.terminal)} m/s`,`D = ${f(m.drag)} N`,`mg = ${f(s.mass*g)} N`],750,120)+note('Quadratic drag D=½CρAv², C=1, ρ=1.2 kg/m³; released from rest; no ground in this air column.');},[step('Choose a drag model','For the assumed turbulent regime, drag magnitude is proportional to effective area and speed squared.','D = ½CρAv² = bv²','The canopy width grows with √A so its represented area grows with A.'),step('Balance forces at terminal speed','The terminal condition is zero acceleration, not zero velocity.','mg=bv_t²; v_t=√(mg/b)','At late times the upward drag arrow approaches the downward weight arrow.'),step('Follow the transient','Initially v=0 so drag is zero. The falling body accelerates less as drag grows.','v(t)=v_t tanh(gt/v_t)','Increasing area lowers terminal speed and visibly slows the descent.')],(s,m)=>target(`Mass ${s.mass} kg, canopy A=${s.area} m², C=1, air density 1.2 kg/m³, g=9.8. Find terminal speed.`,m.terminal,'m/s',[`b=½CρA=${f(m.b)} kg/m`,`v_t=√(mg/b)=√(${s.mass}×9.8/${f(m.b)})=${f(m.terminal)} m/s`]),physical(6),[7,8,9],'§6.2 turbulent quadratic drag and terminal speed; exact rest-release tanh transient under constant coefficients.');

// Chapter6 direction glyphs are separate from the proportional force-magnitude ledger.
// Keep circularScene/4.5 unchanged: its kinematic arrows retain their existing scales.
function circularForceScene(s,m,t){
 const cx=340,cy=275,rr=s.radius*50,theta=s.speed*t/s.radius,x=cx+rr*Math.cos(theta),y=cy-rr*Math.sin(theta),barX=630,barY=374,barScale=1.4,barWidth=180*barScale;
 let q=head('The inward net force continually turns the velocity')+P(`M${cx+rr},${cy} A${rr},${rr} 0 1 0 ${cx-rr},${cy} A${rr},${rr} 0 1 0 ${cx+rr},${cy}`,'line',3)+L(cx,cy,x,y,'line',2)+ball(x,y,s.mass);
 // These fixed-length glyphs encode direction only, never force or speed magnitude.
 q+=A(x,y,x-45*Math.sin(theta),y-45*Math.cos(theta),'coral',3)+A(x,y,x-60*Math.cos(theta),y+60*Math.sin(theta),'aqua',3);
 q+=info([`r = ${s.radius} m`,`speed = ${s.speed} m/s`,`a = ${f(m.accel)} m/s²`,`F = ${f(m.force)} N`]);
 q+=T(750,285,'Coral: velocity direction only',15,'coral')+T(750,315,'Aqua: inward-force direction only',15,'aqua')+T(756,354,'Force magnitude · fixed 0–180 N',15);
 q+=R(barX,barY,barWidth,18,'surface',0)+`<rect data-gp-force-bar="6.3" x="${barX}" y="${barY}" width="${barScale*m.force}" height="18" fill="${K.color('aqua')}"/>`;
 for(const force of[0,30,60,90,120,150,180]){const xx=barX+barScale*force;q+=L(xx,barY+20,xx,barY+26,'wire',1);if(force%60===0)q+=T(xx,barY+45,`${force}`,13);}
 return q+T(756,448,'Force bar: 1.4 px/N; numbers above give N',13,'muted')+note('Direction arrows only: coral v, aqua inward F. Magnitude: fixed force bar. Radius: 50 px/m; no extra force.');
}
def('6.3','Supply the inward force for a circular ride','Mass, speed, and radius determine the inward resultant needed to keep a bead on its circular guide. Centripetal means inward; it is not an extra force.',[N('mass','Bead mass',1,5,1,2,'kg'),N('radius','Guide radius',1,3,.5,2,'m'),N('speed','Constant speed',1,6,.5,3,'m/s')],s=>({accel:s.speed*s.speed/s.radius,force:s.mass*s.speed*s.speed/s.radius,readouts:[r('Required inward net force',s.mass*s.speed*s.speed/s.radius,'N'),r('Inward acceleration',s.speed*s.speed/s.radius,'m/s²')]}),(s,m,t)=>circularForceScene(s,m,t),[step('Change direction with a real force','A circular path requires a nonzero inward resultant even at constant speed.','a_r=v²/r','The velocity arrow remains tangent; the guide’s resultant points inward.'),step('Apply the second law radially','The required force is mass times inward acceleration.','ΣF_inward=mv²/r','Increasing bead mass strengthens the force bar without changing the path or acceleration.'),step('Compare speed and radius','Doubling speed quadruples the required force; doubling radius halves it.','F_inward ∝ mv²/r','Direction-only arrows stay clearly visible; the separate force bar uses a fixed 0–180 N scale.')],(s,m)=>target(`For mass ${s.mass} kg, speed ${s.speed} m/s, radius ${s.radius} m, find inward net force.`,m.force,'N',[`F=mv²/r`,`F=${s.mass}×${s.speed}²/${s.radius}=${f(m.force)} N`]),physical(12),[10,11,12],'§6.3 circular-motion dynamics; schematic horizontal guide supplies resultant force.');

def('7.1','Send energy down an air track','A moving cart carries kinetic energy. Changing speed changes its energy quadratically, while changing mass changes the energy in direct proportion.',[N('mass','Cart mass',1,5,1,2,'kg'),N('speed','Cart speed',0,10,1,4,'m/s')],s=>({energy:.5*s.mass*s.speed*s.speed,x:s.speed*s.time,readouts:[r('Kinetic energy',.5*s.mass*s.speed*s.speed,'J'),r('Speed',s.speed,'m/s')]}),(s,m)=>head('Twice the speed carries four times the kinetic energy')+rail(370)+cart(100+18*m.x,340,s.mass,`${s.mass} kg`)+vec(100+18*m.x,280,s.speed,0,7,'coral','v')+energy(800,420,'K',m.energy,250)+note('Ideal unforced motion at constant velocity. Fixed track scale 18 px/m; energy vessel maximum 250 J.'),[step('Use the chosen reference frame','Kinetic energy depends on speed relative to the observer, not just the object’s identity.','K=½mv²','The track is the reference frame used for the displayed speed.'),step('Compare masses','At equal speed, twice the moving mass carries twice the kinetic energy.','K ∝ m at fixed v','The larger cart and taller energy fill respond to increased mass.'),step('Square the speed','Doubling speed multiplies kinetic energy by four. Energy has no directional sign.','K ∝ v²','Compare cart travel and reservoir height when speed doubles.')],(s,m)=>target(`A ${s.mass} kg cart moves at ${s.speed} m/s. Find its kinetic energy.`,m.energy,'J',[`K=½mv²`,`K=½(${s.mass})(${s.speed})²=${f(m.energy)} J`]),physical(4),[1,2],'§7.1 kinetic energy as a scalar, mass and speed dependence.');

def('7.2','Pull a cart at an angle','Only the force component along the displacement does work. The vertical component is balanced by the track and contributes no work while the cart stays horizontal.',[N('force','Pull magnitude',2,12,1,8,'N'),N('angle','Pull elevation',0,80,10,40,'°'),N('distance','Measurement endpoint',1,8,1,5,'m')],s=>{let fx=s.force*Math.cos(rad(s.angle)),a=fx/2,end=Math.sqrt(2*s.distance/a),t=Math.min(s.time,end),x=.5*a*t*t;return{fx,a,end,t,x,work:fx*x,total:fx*s.distance,v:a*t,readouts:[r('Work delivered so far',fx*x,'J'),r('Kinetic energy gained',fx*x,'J'),r('Final-endpoint work',fx*s.distance,'J')]};},(s,m)=>head('The component parallel to travel transfers energy')+rail(370)+cart(120+65*m.x,340,2,'2 kg cart')+vec(120+65*m.x,275,s.force*Math.cos(rad(s.angle)),s.force*Math.sin(rad(s.angle)),9,'coral','pull')+A(120,405,120+65*s.distance,405,'aqua',3)+T(120+32.5*s.distance,435,`${s.distance} m displacement`,16)+info([`F_parallel=${f(m.fx)} N`,`W=${f(m.work)} J`,`ΔK=${f(m.work)} J`],750,125)+note('Frictionless horizontal track. Clock freezes on reaching the chosen endpoint; this is not a braking model.'),[step('Resolve along the displacement','The component perpendicular to motion cannot contribute to F·dr on this horizontal track.','F_parallel=F cos θ','Rotating the pull changes its horizontal component and the cart acceleration.'),step('Compute work','A constant force transfers its parallel component times the distance.','W=Fd cos θ','The aqua endpoint arrow measures the displacement in the work calculation.'),step('Connect work to motion','With no other horizontal force, net work is the change in kinetic energy.','ΔK=W; v²=2W/m','A larger useful pull both moves the cart faster and increases its kinetic-energy gain.')],(s,m)=>target(`F=${s.force} N pulls at ${s.angle}° above a horizontal displacement ${s.distance} m. Find its work.`,m.total,'J',[`F_parallel=${s.force} cos(${s.angle}°)=${f(m.fx)} N`,`W=F_parallel d=${f(m.total)} J`]),physical(10),[3,4,5,6],'§7.2 work dot product and work–kinetic-energy theorem. Track keeps vertical motion zero; force ranges preserve contact (mg > F_y).');

def('7.3','Lift a load against gravity','A controlled hoist raises a load. Gravity does negative work during the upward displacement; the slow hoist supplies equal positive work.',[N('mass','Load mass',1,10,1,4,'kg'),N('height','Lift height',1,8,1,5,'m')],s=>({height:s.height*Math.min(s.time/8,1),work:-s.mass*g*s.height,readouts:[r('Gravity work for whole lift',-s.mass*g*s.height,'J'),r('Current height',s.height*Math.min(s.time/8,1),'m')]}),(s,m,t)=>{let y=420-28*m.height;return head('Gravity and upward displacement have opposite directions')+L(350,90,350,y-25,'wire',4)+C(350,90,27,'surface')+R(350-10*Math.sqrt(s.mass),y-25,20*Math.sqrt(s.mass),45,'coral',3)+vec(450,y,0,-s.mass*g,.4,'coral','mg')+A(240,420,240,420-28*s.height,'aqua',3)+T(200,280,`${s.height} m`,16)+L(130,445,580,445,'wire',4)+info([`W_gravity = ${f(m.work)} J`,`W_hoist = ${f(-m.work)} J`,`constant slow lift`],755,160)+note('Controlled quasistatic lift; illustration clock moves the hoist, with start/stop transients omitted. 28 px/m.');},[step('Identify the force direction','Gravity points downward even when the load travels upward.','F_g=−mg ĵ','The coral gravity arrow opposes the aqua upward displacement.'),step('Take the dot product','Opposite directions produce negative work.','W_g=−mgΔy','Increasing height lengthens the lift and increases the magnitude of gravity’s work.'),step('Account for the hoist','For a quasistatic lift with no net kinetic-energy change, the hoist balances gravity.','W_hoist+W_g=ΔK=0','Positive hoist work becomes increased gravitational potential energy.')],(s,m)=>target(`A ${s.mass} kg load rises ${s.height} m with g=9.8 m/s². Find the work done by gravity.`,m.work,'J',[`W_g=−mgΔy`,`W_g=−(${s.mass})(9.8)(${s.height})=${f(m.work)} J`]),staged(),[7,8,9,10],'§7.3 gravitational work; original quasistatic crane. No claim of freely accelerated lift.');

function springModel(s){let omega=Math.sqrt(s.k/s.mass),x=s.amplitude*Math.cos(omega*s.time),v=-s.amplitude*omega*Math.sin(omega*s.time),U=.5*s.k*x*x,Kinetic=.5*s.mass*v*v;return{x,v,force:-s.k*x,U,Kinetic,total:.5*s.k*s.amplitude*s.amplitude,omega,readouts:[r('Displacement',x,'m'),r('Spring force',-s.k*x,'N'),r('Spring potential energy',U,'J'),r('Kinetic energy',Kinetic,'J')]};}
function springScene(s,m,t,well=false){let sc=well?80:160,cx=well?350:390,x=cx+sc*m.x,q=head(well?'Turning points occur where all energy is potential':'The spring force reverses when the stretch reverses')+rail(365)+R(80,260,18,100,'surface',2);if(well)q+=R(cx-sc*s.amplitude,325,2*sc*s.amplitude,34,'aqua',2)+L(cx-sc*s.amplitude,240,cx-sc*s.amplitude,370,'line',2)+L(cx+sc*s.amplitude,240,cx+sc*s.amplitude,370,'line',2);q+=spring(98,x-25,320)+cart(x,336,s.mass,`${s.mass} kg`)+vec(x,250,m.force,0,2,'aqua','spring F')+vec(x,180,m.v,0,12,'coral','v')+L(cx,280,cx,374,'line',1)+T(cx,410,'equilibrium x=0',14)+energy(730,425,'U_s',m.U,well?12:15,'aqua')+energy(845,425,'K',m.Kinetic,well?12:15);return q+note(well?'Shaded rail marks the accessible interval ±√(2E/k). No primary energy plot; exact ideal spring motion.':'Hooke’s-law spring, no friction. Position160 px/m; force2 px/N; velocity12 px/(m/s).');}
def('7.4','Exchange spring energy with a moving cart','Release a stretched spring from rest. Its restoring force changes with displacement; work transferred from the spring becomes cart kinetic energy.',[N('k','Spring stiffness',5,30,5,15,'N/m'),N('mass','Cart mass',1,4,1,2,'kg'),N('amplitude','Release stretch',.1,1,.1,.6,'m')],springModel,(s,m,t)=>springScene(s,m,t),[step('Use a restoring force','A stretched spring pulls back; a compressed spring pushes back.','F_s=−kx','The aqua force arrow points toward equilibrium on both sides.'),step('Integrate the changing force','A spring’s force is not constant, so its work depends on squared endpoint stretches.','W_s=½k(x_i²−x_f²)','The spring shortens while its potential-energy vessel drains.'),step('Transfer energy to motion','Starting from rest at A, the cart gains the energy released by the spring.','K=½k(A²−x²)','The kinetic-energy vessel fills fastest near equilibrium, where speed is greatest.')],(s,m)=>{let x=Number(f(m.x)),W=.5*s.k*(s.amplitude*s.amplitude-x*x);return target(`Spring stiffness ${s.k} N/m, release stretch A=${s.amplitude} m. Using x=${f(x)} m, find work done by the spring from release to this position.`,W,'J',[`W_s=½k(A²−x²)`,`W_s=½(${s.k})(${s.amplitude}²−${f(x)}²)=${f(W)} J`]);},physical(12),[11,12,13,14],'§7.4 Hooke’s law, integrated spring work, work–energy theorem. Exact harmonic motion for ideal spring.');

def('7.5','Program a position-dependent pulling force','A linear actuator pulls a sled with F(x)=bx, measured from a fixed origin. Its force grows as the sled travels, so work must add the changing force over the path.',[N('b','Force gradient b',1,6,1,3,'N/m'),N('mass','Sled mass',1,4,1,2,'kg'),N('end','Final position',2,5,1,4,'m')],s=>{let omega=Math.sqrt(s.b/s.mass),endTime=Math.acosh(s.end)/omega,t=Math.min(s.time,endTime),x=Math.cosh(omega*t),v=omega*Math.sinh(omega*t);return{x,v,force:s.b*x,work:.5*s.b*(x*x-1),total:.5*s.b*(s.end*s.end-1),endTime,readouts:[r('Actuator force',s.b*x,'N'),r('Work delivered',.5*s.b*(x*x-1),'J'),r('Final-endpoint work',.5*s.b*(s.end*s.end-1),'J')]};},(s,m,t)=>{let x=160+85*(m.x-1);return head('A changing force transfers different work in each meter')+rail(365)+R(95,115,145,62,'surface',4)+T(167,151,`F(x) = ${s.b} x`,19)+cart(x,335,s.mass,'actuator sled')+vec(x,270,m.force,0,4,'coral','F(x)')+L(160,410,160+85*(s.end-1),410,'aqua',4)+T(160,442,'x=1 m',14)+T(160+85*(s.end-1),442,`x=${s.end} m`,14)+info([`x=${f(m.x)} m`,`F=${f(m.force)} N`,`W=${f(m.work)} J`],750,140)+note('Ideal programmable actuator; starts at x=1 m from rest. Clock freezes at endpoint. Force is not a spring restoring force.');},[step('Read a force rule, not one value','The applied force grows with position, so no single constant force represents the whole trip.','F(x)=bx','The coral force arrow grows as the sled moves right.'),step('Add small work contributions','Over each tiny displacement the local force is nearly constant.','W=∫ from 1 to x F(x′) dx′','The position ruler shows the interval over which force must be accumulated.'),step('Integrate and check energy','Integrating bx gives a difference of squared positions. Newton’s law gives the same kinetic-energy increase.','W=½b(x²−1²)=½mv²','The accelerating sled displays how the transferred work becomes motion.')],(s,m)=>target(`An actuator applies F(x)=(${s.b} N/m)x. Find its work from x=1 m to x=${s.end} m.`,m.total,'J',[`W=∫₁^${s.end} bx dx=½b(${s.end}²−1²)`,`W=½(${s.b})(${s.end}²−1)=${f(m.total)} J`]),physical(4),[14,15,16,17],'§7.5 general variable-force integration; original actuator, exact x=cosh(√(b/m)t), no hidden constant-force assumption.');

def('7.6','Drive a load with a powered winch','Raise the same load faster or lift a heavier load in the same time. The motor power measures energy transferred per second, not just total work.',[N('mass','Load mass',1,10,1,4,'kg'),N('height','Lift distance',1,8,1,5,'m'),N('duration','Steady lift duration',2,10,1,5,'s')],s=>{let t=Math.min(s.time,s.duration),v=s.height/s.duration;return{t,v,y:v*t,power:s.mass*g*v,work:s.mass*g*v*t,total:s.mass*g*s.height,readouts:[r('Steady upward speed',v,'m/s'),r('Motor mechanical power',s.mass*g*v,'W'),r('Work delivered',s.mass*g*v*t,'J')]};},(s,m,t)=>{let y=425-28*m.y,a=m.y/0.3,q=head('Power is the rate of doing work')+C(350,100,35,'surface')+L(350,100,350+28*Math.cos(a),100+28*Math.sin(a),'coral',4)+L(350,130,350,y-25,'wire',3)+R(350-10*Math.sqrt(s.mass),y-25,20*Math.sqrt(s.mass),45,'aqua',3)+T(350,y+5,`${s.mass} kg`,15,'paper')+vec(450,y,0,m.v,15,'coral','v up')+L(180,450,560,450,'wire',4);for(let i=0;i<Math.min(12,Math.ceil(m.power/50));i++)q+=C(650+(i%4)*45,290+Math.floor(i/4)*35,7,'coral');return q+info([`P = ${f(m.power)} W`,`work = ${f(m.work)} J`,`v = ${f(m.v)} m/s`],770,110)+note('Steady controlled lift, no losses. Start/stop transients omitted; time freezes at chosen lift duration.');},[step('Compute the total work','Raising the load at constant speed requires a lifting force equal to mg.','W=mgh','A heavier or higher lift requires more total transferred energy.'),step('Divide by lift duration','Power distinguishes a fast lift from a slow lift with the same work.','P_avg=W/T','Changing duration changes hoist speed and motor power.'),step('Use force and velocity','For this steady vertical lift, force and velocity are parallel.','P=F·v=mg(h/T)','The motor’s energy markers and rotating drum respond to the transfer rate.')],(s,m)=>target(`A lossless winch lifts ${s.mass} kg through ${s.height} m in ${s.duration} s at steady speed, g=9.8. Find mechanical power.`,m.power,'W',[`W=mgh=${f(m.total)} J`,`P=W/T=${f(m.total)}/${s.duration}=${f(m.power)} W`]),physical(10),[18,19],'§7.6 power W/Δt and instantaneous F·v; constant-speed lift with omitted boundary transients.');

def('8.1','Take two routes to the same height','A controlled carrier lifts a mass along a direct route or a sideways detour. Gravitational potential energy depends on the endpoint height, not the route.',[N('mass','Carried mass',1,8,1,3,'kg'),N('height','Final height',1,8,1,5,'m'),O('path','Lift route','direct',[['direct','Direct vertical lift'],['detour','Sideways detour']])],s=>{let p=Math.min(s.time/8,1);return{p,y:s.height*p,x:s.path==='detour'?120*Math.sin(pi*p):0,U:s.mass*g*s.height*p,total:s.mass*g*s.height,readouts:[r('Current gravitational potential energy',s.mass*g*s.height*p,'J'),r('Final potential-energy increase',s.mass*g*s.height,'J')]};},(s,m,t)=>{let d='';for(let i=0;i<=60;i++){let p=i/60;d+=`${i?'L':'M'}${320+(s.path==='detour'?120*Math.sin(pi*p):0)},${420-28*s.height*p}`;}return head('Conservative work depends only on the endpoints')+P(d,'line',3)+ball(320+m.x,420-28*m.y,s.mass)+vec(365+m.x,420-28*m.y,0,-s.mass*g,.6,'coral','mg')+T(780,190,'Gravity arrow: 0.6 px/N',13,'coral')+A(190,420,190,420-28*s.height,'aqua',3)+T(160,285,`${s.height} m`,16)+L(110,450,590,450,'wire',4)+energy(780,425,'U_g',m.U,630,'aqua')+note('Controlled path construction, not free fall. Zero gravitational potential is the bottom height; 28 px/m vertically.');},[step('Define a system and zero','Potential energy belongs to the mass–Earth system. Only differences matter.','U_g=mg y, with U_g(0)=0','The bottom endpoint is the common reference height.'),step('Compare routes','Gravity is vertical, so sideways displacement contributes zero gravitational work.','ΔU_g=mgΔy=−W_g','Choose the detour: extra sideways motion leaves the endpoint energy unchanged.'),step('Track energy transfer','A slow carrier supplies the potential-energy increase without a net kinetic-energy increase.','W_carrier=ΔU_g','The potential-energy vessel fills as height rises.')],(s,m)=>target(`A ${s.mass} kg mass is lifted ${s.height} m by the selected route, g=9.8. Find ΔU of the mass–Earth system.`,m.total,'J',[`ΔU=mgΔy, independent of path`,`ΔU=${s.mass}×9.8×${s.height}=${f(m.total)} J`]),staged(),[1,2,3,4,5],'§8.1 conservative forces and gravitational potential energy; original prescribed direct/detour paths.');

def('8.2','Trade height for speed on a frictionless ramp','Release a cart from rest on a smooth straight ramp. The normal force does no work, so lost gravitational potential energy becomes kinetic energy.',[N('height','Release height',1,3,.5,2,'m'),N('angle','Ramp angle',25,65,10,45,'°'),N('mass','Cart mass',1,5,1,2,'kg')],s=>{let angle=rad(s.angle),length=s.height/Math.sin(angle),a=g*Math.sin(angle),endTime=Math.sqrt(2*length/a),t=Math.min(s.time,endTime),distance=.5*a*t*t,y=Math.max(0,s.height-distance*Math.sin(angle)),v=a*t;return{angle,length,a,endTime,t,distance,y,v,U:s.mass*g*y,Kinetic:.5*s.mass*v*v,total:s.mass*g*s.height,readouts:[r('Cart height',y,'m'),r('Cart speed',v,'m/s'),r('Mechanical energy',s.mass*g*s.height,'J')]};},(s,m,t)=>{let x=120+80*m.distance*Math.cos(m.angle),y=420-80*m.y,end=120+80*s.height/Math.tan(m.angle);return head('Changing ramp steepness changes the time, not the final speed')+L(120,420-80*s.height,end,420,'wire',5)+cart(x,y-18,s.mass,'')+T(x-65,y-65,'ramp cart',14)+C(590,155,5,'surface')+vec(590,155,m.a*Math.cos(m.angle),-m.a*Math.sin(m.angle),6,'aqua','a down ramp')+energy(745,425,'U_g',m.U,150,'aqua')+energy(860,425,'K',m.Kinetic,150)+note('Ideal pointlike cart slides without rolling/friction. Equal position scale80 px/m; clock freezes at ramp bottom.');},[step('Choose the isolated system','With the cart and Earth included, gravity transfers energy internally. The ramp normal is perpendicular to travel.','E_mech=K+U_g','The apparatus has no friction or motor input.'),step('Conserve mechanical energy','Every joule lost from gravitational potential appears in kinetic energy.','½mv²+mgy=mgh','The two energy vessels exchange fill while their sum stays fixed.'),step('Cancel the mass','The same mass multiplies kinetic and gravitational energies.','v=√[2g(h−y)]','Changing mass alters the energy amounts but leaves the speed at a given height unchanged.')],(s,m)=>target(`A frictionless cart starts from rest ${s.height} m above the ramp bottom, g=9.8. Find speed at the bottom.`,Math.sqrt(2*g*s.height),'m/s',[`mgh=½mv²; mass cancels`,`v=√(2×9.8×${s.height})=${f(Math.sqrt(2*g*s.height))} m/s`]),physical(4),[8,9,10,11],'§8.2 mechanical-energy conservation. Straight ramp special case; no rolling kinetic energy.');

def('8.3','Find turning points in a spring energy well','An ideal spring confines the cart to positions where its potential energy is no larger than its total energy. The shaded track is the allowed region; its edges are turning points.',[N('energy','Total mechanical energy',2,12,2,6,'J'),N('k','Spring stiffness',5,20,5,10,'N/m'),N('mass','Cart mass',1,3,1,2,'kg')],s=>springModel({...s,amplitude:Math.sqrt(2*s.energy/s.k)}),(s,m,t)=>springScene({...s,amplitude:Math.sqrt(2*s.energy/s.k)},m,t,true),[step('Read force from potential','The force is the negative position derivative of potential, not the potential itself.','U=½kx²; F=−dU/dx=−kx','The spring force points toward the minimum-energy position x=0.'),step('Identify allowed positions','Kinetic energy cannot be negative, so only U≤E is accessible.','K=E−U≥0','The shaded rail spans the region allowed by the chosen energy.'),step('Locate turning points','At a turning point the velocity is zero and all mechanical energy is potential.','x_turn=±√(2E/k)','The cart reverses at the two boundary markers; equilibrium is at the central minimum.')],(s,m)=>target(`For U(x)=½kx², k=${s.k} N/m and total E=${s.energy} J, find the positive turning-point coordinate.`,Math.sqrt(2*s.energy/s.k),'m',[`At turning point K=0, so E=½kx²`,`x_positive=√(2E/k)=${f(Math.sqrt(2*s.energy/s.k))} m`]),physical(12),[11,12,13,14,15],'§8.3 force from negative potential gradient, allowed regions, turning points and stable equilibrium; physical spring replaces a primary potential plot.');

def('8.4','Push energy into a rough-track system','A motor pushes a block over a rough surface. External work becomes both kinetic energy and thermal energy in the block–track system.',[N('force','Applied horizontal force',15,30,5,20,'N'),N('mu','Kinetic friction coefficient',0,.4,.1,.2),N('mass','Block mass',1,3,.5,2,'kg'),N('distance','Measurement distance',1,6,1,4,'m')],s=>{let friction=s.mu*s.mass*g,a=(s.force-friction)/s.mass,endTime=Math.sqrt(2*s.distance/a),t=Math.min(s.time,endTime),x=.5*a*t*t,work=s.force*x,heat=friction*x;return{friction,a,endTime,x,work,heat,Kinetic:work-heat,finalHeat:friction*s.distance,readouts:[r('External work supplied',work,'J'),r('Kinetic-energy gain',work-heat,'J'),r('Thermal-energy gain',heat,'J')]};},(s,m,t)=>{let x=140+65*m.x,q=head('External work feeds two energy destinations')+rail(375)+R(x-25,305,50,60,'surface',4)+T(x,340,`${s.mass} kg`,14)+vec(x,275,s.force,0,4,'coral','external F')+vec(x,215,-m.friction,0,4,'aqua','friction')+energy(740,425,'ΔK',m.Kinetic,180)+energy(855,425,'ΔE_th',m.heat,180,'aqua');for(let i=0;i<Math.ceil(s.mu*20);i++)q+=P(`M${100+i*55},375 l10,-8 l10,8`,'line',2);return q+note('Block + track is the system; friction transfers energy internally. Clock freezes at the chosen distance.');},[step('Define the system boundary','For the block–track system the motor force is external; friction redistributes energy within the system.','W_external=ΔK+ΔE_th','The coral force injects energy into the block and track together.'),step('Count thermal energy','Sliding friction raises thermal energy according to friction force times sliding distance.','ΔE_th=f_kd=μ_kmgd','The aqua energy vessel measures energy no longer available as cart motion.'),step('Balance the full transfer','Mechanical-energy gain is smaller than external work when friction is present.','ΔK=Fd−μ_kmgd','Increasing roughness sends more input energy into heat and less into motion.')],(s,m)=>target(`A ${s.mass} kg block slides ${s.distance} m with μk=${s.mu}, g=9.8. Find the block–track thermal-energy gain.`,m.finalHeat,'J',[`f_k=μ_kmg=${f(m.friction)} N`,`ΔE_th=f_kd=${f(m.friction)}×${s.distance}=${f(m.finalHeat)} J`]),physical(3),[15,16,17,18],'§8.4 external work and thermal energy. Force controls always exceed kinetic friction; block starts sliding from rest.');

def('8.5','Stop a sled without losing total energy','A launched sled slows on a rough track. Kinetic energy decreases while the thermal energy of the sled–track system increases by exactly the same amount.',[N('mass','Sled mass',1,5,1,2,'kg'),N('speed','Launch speed',1,8,1,5,'m/s'),N('mu','Kinetic friction coefficient',.1,.5,.1,.2)],s=>{let a=s.mu*g,stop=s.speed/a,t=Math.min(s.time,stop),v=s.time>=stop?0:Math.max(0,s.speed-a*t),x=s.speed*t-.5*a*t*t,initial=.5*s.mass*s.speed*s.speed,Kinetic=.5*s.mass*v*v;return{a,stop,t,v,x,initial,Kinetic,heat:initial-Kinetic,stopDistance:s.speed*s.speed/(2*a),readouts:[r('Remaining kinetic energy',Kinetic,'J'),r('Thermal-energy gain',initial-Kinetic,'J'),r('Total energy',initial,'J'),r('Stopping distance',s.speed*s.speed/(2*a),'m')]};},(s,m,t)=>{let x=130+17*m.x,q=head('Friction changes energy form; it does not destroy energy')+rail(375)+cart(x,345,s.mass,'braking sled')+vec(x,275,m.v,0,10,'coral','v')+(m.v>0?vec(x,215,-s.mu*s.mass*g,0,2,'aqua','friction'):T(x,215,'at rest: friction = 0',14))+energy(750,425,'K',m.Kinetic,160)+energy(860,425,'E_th',m.heat,160,'aqua');for(let i=0;i<Math.ceil(Math.min(20,m.heat/4));i++)q+=C(140+(i%10)*48,405+Math.floor(i/10)*18,3,'aqua');return q+note('Isolated sled + track energy model, no drag. Clock stops the sled at rest and does not let friction reverse it.');},[step('Include the thermal store','Friction converts organized motion into internal thermal energy. A mechanical-energy-only total is incomplete.','E_total=K+E_th','The two energy fills sum to the original launch energy.'),step('Use a stopping event','Kinetic friction opposes the motion only while the sled slides. At rest it cannot accelerate the sled backward.','v=max(v₀−μ_kgt,0)','After the stopping time the sled and energy readouts remain fixed.'),step('Calculate the stopping distance','All initial kinetic energy becomes thermal energy, μmgd. The mass cancels from distance.','½mv₀²=μ_kmgd; d=v₀²/(2μ_kg)','A rougher track stops the sled sooner but produces the same final heat at fixed mass and launch speed.')],(s,m)=>target(`A sled starts at ${s.speed} m/s on a level track with μk=${s.mu}, g=9.8. Find stopping distance.`,m.stopDistance,'m',[`½mv₀²=μ_kmgd; cancel m`,`d=${s.speed}²/(2×${s.mu}×9.8)=${f(m.stopDistance)} m`]),physical(10),[19,20,21],'§8.5 total energy with thermal conversion. Exact constant kinetic-friction braking, no motion after stopping.');
Object.assign(window.GlassPhysicsRegistry,D);
})();
